'use strict';

// MODULES //

import { isPrimitive as isPositiveInteger } from '@stdlib/assert-is-positive-integer';
import incrmmaxabs from '@stdlib/stats-incr-mmaxabs';
import isnan from '@stdlib/math-base-assert-is-nan';
import format from '@stdlib/error-tools-fmtprodmsg';


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving maximum absolute value while ignoring NaN values.
*
* @param {PositiveInteger} W - window size
* @throws {TypeError} must provide a positive integer
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmmaxabs( 3 );
*
* var m = accumulator();
* // returns null
*
* m = accumulator( 2.0 );
* // returns 2.0
*
* m = accumulator( NaN );
* // returns 2.0
*
* m = accumulator( -5.0 );
* // returns 5.0
*
* m = accumulator( 3.0 );
* // returns 5.0
*
* m = accumulator( NaN );
* // returns 5.0
*
* m = accumulator( 5.0 );
* // returns 5.0
*
* m = accumulator();
* // returns 5.0
*/
function incrnanmmaxabs( W ) {
	var max;
	if ( !isPositiveInteger( W ) ) {
		throw new TypeError( format( 'null8B', W ) );
	}
	max = incrmmaxabs( W );
	return accumulator;

	/**
	* If provided a value, the accumulator function returns an updated maximum absolute value. If not provided a value, the accumulator function returns the current maximum absolute value.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(number|null)} maximum absolute value or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 || isnan( x ) ) {
			return max();
		}
		return max( x );
	}
}


// EXPORTS //

export default incrnanmmaxabs;
